/* Month grid with posting stamps, direct shot-list navigation, and pointer rescheduling. */
var CalendarUI = {
  drag:null, frame:0, suppressUntil:0,
  render() {
    const query=($('#agendaSearch').value||'').toLowerCase(),first=new Date(month.getFullYear(),month.getMonth(),1),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(first.getDay()+6)%7,total=Math.ceil((offset+days)/7)*7;
    const topics=state.topics.filter(t=>(t.title+' '+t.summary+' '+t.platform).toLowerCase().includes(query));
    $('#agenda').innerHTML=`<div class="calendar-weekdays">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>`<span class="${i===6?'sunday-heading':''}">${d}</span>`).join('')}</div><div class="calendar-grid" style="--weeks:${total/7}">${Array.from({length:total},(_,i)=>{const day=new Date(month.getFullYear(),month.getMonth(),i-offset+1),date=localDate(day),items=topics.filter(t=>t.date===date).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));return `<section class="calendar-cell ${day.getMonth()!==month.getMonth()?'outside-month':''} ${day.getDay()===0?'is-sunday':''} ${date===localDate(today)?'is-today':''}" data-day="${date}"><div class="cell-date"><span class="cell-number">${day.getDate()}</span>${date===localDate(today)?'<span class="today-label">Today</span>':''}${items.length>1?`<span class="cell-count">${items.length} items</span>`:''}</div><div class="cell-topics">${items.map(t=>`<article class="calendar-topic ${t.status==='Published'?'is-posted':''}" data-agenda="${escapeHTML(t.id)}" style="--topic-color:${validColor(t.color)}"><button class="calendar-topic-open" data-open-calendar="${escapeHTML(t.id)}" title="${escapeHTML(t.title)} · Open shot sequencer"><span class="calendar-topic-title">${escapeHTML(t.title)}</span><span class="calendar-topic-meta">${t.time?formatTime(t.time):escapeHTML(t.platform)}</span></button><div class="calendar-card-footer"><span>${CanvasEditor.sequenceForBoard(t.boardId)?'Shot list ready':'Content plan'}</span><button class="calendar-posted" data-posted="${escapeHTML(t.id)}" aria-label="${t.status==='Published'?'Unmark':'Mark'} ${escapeHTML(t.title)} ${t.status==='Published'?'posted':'as posted'}" aria-pressed="${t.status==='Published'}">${icon('check')}<span>${t.status==='Published'?'Posted':'Mark posted'}</span></button></div></article>`).join('')}</div></section>`}).join('')}</div>`;
    $$('[data-open-calendar]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(Date.now()<this.suppressUntil)return;this.open(b.dataset.openCalendar)});
    $$('[data-posted]').forEach(b=>b.onclick=e=>{e.stopPropagation();this.posted(b.dataset.posted)});
    $$('[data-agenda]').forEach(card=>{card.onpointerdown=e=>this.start(e,card);card.oncontextmenu=e=>{e.preventDefault();context(e,[['sequence','Open shot sequencer',()=>this.open(card.dataset.agenda)],['calendar','Set date & time',()=>scheduleEditor(card.dataset.agenda)],['text','Open content',()=>openContentCard(card.dataset.agenda)]])}});
    $$('[data-day]').forEach(cell=>cell.ondblclick=e=>{if(!e.target.closest('[data-agenda]'))chooseTopicForDate(cell.dataset.day)});
  },
  posted(id) { const t=state.topics.find(t=>t.id===id);if(!t)return;checkpoint();if(t.status==='Published'){t.status=t.beforePostedStatus||'In progress';delete t.postedAt;}else{t.beforePostedStatus=t.status;t.status='Published';t.postedAt=new Date().toISOString();}save();renderOverview(); },
  open(id) {
    const t=state.topics.find(t=>t.id===id);if(!t)return;const sequence=CanvasEditor.sequenceForBoard(t.boardId);if(sequence){openShotSequence(sequence.id);return;}
    showModal(`<div class="modal-header"><div><div class="eyebrow">${escapeHTML(t.title)}</div><h2 id="modalTitle">No shot sequencer yet.</h2><p>This content doesn’t have a shot list. Continue to Content to review its plan.</p></div>${closeButton()}</div><div class="modal-actions"><button class="secondary-btn" data-close>Cancel</button><button class="primary-btn" id="calendarOpenContent">Go to Content${icon('arrow')}</button></div>`);$('#calendarOpenContent').onclick=()=>{closeModal();openContentCard(id)};
  },
  start(e,card) { if(e.button!==0||e.target.closest('[data-posted]'))return;const t=state.topics.find(t=>t.id===card.dataset.agenda);if(!t||t.status==='Published')return;const r=card.getBoundingClientRect();this.drag={id:t.id,card,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,offsetX:e.clientX-r.x,offsetY:e.clientY-r.y,width:r.width,moved:false,target:null};},
  move(e) {
    const d=this.drag;if(!d)return;d.x=e.clientX;d.y=e.clientY;if(!d.moved&&Math.hypot(d.x-d.startX,d.y-d.startY)<6)return;
    if(!d.moved){d.card.setPointerCapture?.(e.pointerId);d.moved=true;d.card.classList.add('calendar-dragging');const ghost=d.card.cloneNode(true);ghost.id='calendarDragGhost';ghost.removeAttribute('data-agenda');ghost.style.width=d.width+'px';document.body.append(ghost);document.body.classList.add('calendar-moving');}
    e.preventDefault();if(!this.frame){const tick=()=>{const current=this.drag;if(!current?.moved){this.frame=0;return;}const ghost=$('#calendarDragGhost');if(ghost)ghost.style.translate=(current.x-current.offsetX)+'px '+(current.y-current.offsetY)+'px';$$('.calendar-drop-target').forEach(c=>c.classList.remove('calendar-drop-target'));const cell=document.elementFromPoint(current.x,current.y)?.closest('[data-day]');current.target=cell?.dataset.day||null;cell?.classList.add('calendar-drop-target');const wrap=$('#overviewView .agenda-wrap'),r=wrap.getBoundingClientRect();if(current.y>r.bottom-38)wrap.scrollTop+=7;else if(current.y<r.top+42)wrap.scrollTop-=7;this.frame=requestAnimationFrame(tick)};this.frame=requestAnimationFrame(tick);}
  },
  finish() { const d=this.drag;if(!d)return;const moved=d.moved,target=document.elementFromPoint(d.x,d.y)?.closest('[data-day]')?.dataset.day||d.target;this.cancel();if(!moved)return;this.suppressUntil=Date.now()+350;const t=state.topics.find(t=>t.id===d.id);if(!t||!target||target===t.date)return;checkpoint();t.date=target;save();renderOverview();toast('Moved to '+formatDate(target,{weekday:'short',month:'short',day:'numeric'})+' · Ctrl Z to undo'); },
  cancel() { if(this.drag)this.drag.card.classList.remove('calendar-dragging');this.drag=null;cancelAnimationFrame(this.frame);this.frame=0;$('#calendarDragGhost')?.remove();$$('.calendar-drop-target').forEach(c=>c.classList.remove('calendar-drop-target'));document.body.classList.remove('calendar-moving'); },
  init() { document.addEventListener('pointermove',e=>this.move(e));document.addEventListener('pointerup',()=>this.finish());document.addEventListener('pointercancel',()=>this.cancel());window.addEventListener('blur',()=>this.cancel());document.addEventListener('keydown',e=>{if(e.key==='Escape')this.cancel()}); }
};
